import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/records_provider.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class RecordEntryScreen extends ConsumerStatefulWidget {
  const RecordEntryScreen({super.key});

  @override
  ConsumerState<RecordEntryScreen> createState() => _RecordEntryScreenState();
}

class _RecordEntryScreenState extends ConsumerState<RecordEntryScreen> {
  final _formKey = GlobalKey<FormState>();
  String _type = 'Note';
  bool _saving = false;
  String? _message;
  final _title = TextEditingController();
  final _summary = TextEditingController();
  final _date = TextEditingController();

  @override
  void dispose() {
    _title.dispose();
    _summary.dispose();
    _date.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Add health record')),
    body: SafeArea(
      child: Form(
        key: _formKey,
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            DropdownButtonFormField<String>(
              initialValue: _type,
              decoration: const InputDecoration(labelText: 'Record type'),
              items: const ['Condition', 'Allergy', 'Medication', 'Surgery', 'Note']
                  .map((value) => DropdownMenuItem(value: value, child: Text(value)))
                  .toList(),
              onChanged: (value) => _type = value ?? 'Note',
            ),
            TextFormField(
              controller: _title,
              decoration: const InputDecoration(labelText: 'Title'),
              maxLength: 160,
              validator: (value) => value == null || value.trim().length < 2 ? 'Enter a title.' : null,
            ),
            TextFormField(
              controller: _summary,
              decoration: const InputDecoration(labelText: 'Summary (optional)'),
              maxLength: 2000,
              maxLines: 3,
            ),
            TextFormField(
              controller: _date,
              decoration: const InputDecoration(labelText: 'Date (YYYY-MM-DD)'),
              validator: (value) => DateTime.tryParse(value ?? '') == null ? 'Enter a valid date.' : null,
            ),
            FilledButton(onPressed: _saving ? null : _save, child: Text(_saving ? 'Saving…' : 'Save record')),
            if (_message != null) ...[const SizedBox(height: 16), Text(_message!)],
          ],
        ),
      ),
    ),
  );

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;
    final memberId = ref.read(activeMemberProvider);
    if (memberId == null) {
      setState(() => _message = 'Select an active member first.');
      return;
    }
    setState(() {
      _saving = true;
      _message = null;
    });
    try {
      await ref.read(mobileApiProvider).addRecord(
        memberId: memberId,
        recordType: _type,
        title: _title.text,
        summary: _summary.text,
        occurredOn: DateTime.parse(_date.text),
      );
      ref.invalidate(memberRecordsProvider);
      if (mounted) Navigator.of(context).pop();
    } catch (_) {
      if (mounted) setState(() => _message = 'Record could not be saved. Check the connection and try again.');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }
}
